// XSD validation of generated request envelopes (task 4.5, Req 25.7).
//
// WHERE `schemas/*.xsd` exist, every envelope generated by the 4.3 mapper tests
// (test/helpers/requestCases.ts) has its Body payload validated with xmllint-wasm against the
// supplied XSDs (scope decision documented in test/helpers/xsd.ts). Until Blocker B1 supplies
// the schemas, that suite is skipped and the run says "B1: schemas not supplied".
// The harness self-test below runs regardless, against a small synthetic schema pair.
import { describe, expect, it } from 'vitest';
import { EL, NS } from '../../src/soap/contract.js';
import { requestEnvelopeCases } from '../helpers/requestCases.js';
import {
  extractBodyPayload,
  listXsdFiles,
  schemaSetFor,
  validateAgainst,
  type SchemaFile,
  type SchemaSet,
} from '../helpers/xsd.js';
import { childElements, find, parseXml } from '../helpers/xmlRead.js';

const B1_SKIP = 'B1: schemas not supplied';

/** Repository root `schemas/`, resolved from this file (apps/bff/test/xsd/). */
const SCHEMAS_DIR = new URL('../../../../schemas/', import.meta.url);
const schemaFiles = listXsdFiles(SCHEMAS_DIR);
const schemasPresent = schemaFiles.length > 0;

describe('XSD validation status (Req 25.7)', () => {
  it(
    schemasPresent
      ? 'schemas/ holds ' + String(schemaFiles.length) + ' XSD file(s): request validation enabled'
      : B1_SKIP + ': request envelope XSD validation is skipped (schemas/ has no *.xsd)',
    () => {
      if (!schemasPresent) {
        // Printed in the run output on purpose so the skip is never silent (no-console applies
        // to logging; this is test-runner output).
        process.stderr.write('[requestXsd] ' + B1_SKIP + ': XSD validation skipped\n');
      }
      expect(schemaFiles.every((f) => f.fileName.toLowerCase().endsWith('.xsd'))).toBe(true);
    },
  );
});

describe.skipIf(!schemasPresent)(
  'generated request envelopes validate against schemas/*.xsd' +
    (schemasPresent ? '' : ' (skipped: ' + B1_SKIP + ')'),
  () => {
    let set: SchemaSet | undefined;
    const schemaSet = (): SchemaSet => (set ??= schemaSetFor(schemaFiles, EL.searchGuestRequest));

    it.each(requestEnvelopeCases())('$name', async ({ xml }) => {
      const result = await validateAgainst(extractBodyPayload(xml), schemaSet());
      expect(result.errors).toEqual([]);
      expect(result.valid).toBe(true);
    });
  },
);

// ---------------------------------------------------------------------------------------------
// Harness self-test: proves discovery, preloaded imports, payload extraction and xmllint-wasm
// validation work before B1 arrives. The schemas are synthetic and test-only: the entry schema
// declares searchGuestRequest in NS.svc with the contract's child order and leaves
// searchCriteria content unchecked; the imported schema (a test-only namespace) types
// maxResults, so a passing document proves the preloaded import resolved.
// ---------------------------------------------------------------------------------------------

const TYPES_NS = 'urn:test:ihg-guest-search:xsd-harness:types';

const SYNTHETIC_TYPES: SchemaFile = {
  fileName: 'synthetic-types.xsd',
  contents: [
    '<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema"',
    '  targetNamespace="' + TYPES_NS + '" elementFormDefault="qualified">',
    '  <xs:simpleType name="MaxResults">',
    '    <xs:restriction base="xs:positiveInteger"><xs:maxInclusive value="200"/></xs:restriction>',
    '  </xs:simpleType>',
    '</xs:schema>',
  ].join('\n'),
};

const SYNTHETIC_SVC: SchemaFile = {
  fileName: 'synthetic-svc.xsd',
  contents: [
    '<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema" xmlns:t="' + TYPES_NS + '"',
    '  targetNamespace="' + NS.svc + '" elementFormDefault="qualified">',
    '  <xs:import namespace="' + TYPES_NS + '" schemaLocation="synthetic-types.xsd"/>',
    '  <xs:element name="searchGuestRequest">',
    '    <xs:complexType><xs:sequence>',
    '      <xs:element name="searchCriteria">',
    '        <xs:complexType>',
    '          <xs:sequence>',
    '            <xs:any namespace="##any" processContents="skip" minOccurs="0" maxOccurs="unbounded"/>',
    '          </xs:sequence>',
    '          <xs:anyAttribute processContents="skip"/>',
    '        </xs:complexType>',
    '      </xs:element>',
    '      <xs:element name="allAttributes" type="xs:boolean"/>',
    '      <xs:element name="allHistory" type="xs:boolean"/>',
    '      <xs:element name="maxResults" type="t:MaxResults"/>',
    '    </xs:sequence></xs:complexType>',
    '  </xs:element>',
    '</xs:schema>',
  ].join('\n'),
};

const SYNTHETIC_FILES = [SYNTHETIC_TYPES, SYNTHETIC_SVC];

/** A minimal hand-written payload; `maxResults` and the root element are parameters. */
const minimal = (maxResults: string, root = 'searchGuestRequest'): string =>
  [
    '<s:' + root + ' xmlns:s="' + NS.svc + '">',
    '<s:searchCriteria status="O"/>',
    '<s:allAttributes>true</s:allAttributes>',
    '<s:allHistory>false</s:allHistory>',
    '<s:maxResults>' + maxResults + '</s:maxResults>',
    '</s:' + root + '>',
  ].join('');

describe('XSD harness self-test (synthetic schemas)', () => {
  const set = schemaSetFor(SYNTHETIC_FILES, EL.searchGuestRequest);

  it('picks the schema declaring searchGuestRequest as entry and preloads the rest', () => {
    expect(set.entry.fileName).toBe('synthetic-svc.xsd');
    expect(set.preload.map((f) => f.fileName)).toEqual(['synthetic-types.xsd']);
  });

  it('fails clearly when no schema declares the payload element', () => {
    expect(() => schemaSetFor([SYNTHETIC_TYPES], EL.searchGuestRequest)).toThrow(
      /exactly one XSD declaring global element .*searchGuestRequest, found 0/,
    );
  });

  it('accepts a valid minimal searchGuestRequest (import resolved from preload)', async () => {
    expect(await validateAgainst(minimal('50'), set)).toEqual({ valid: true, errors: [] });
  });

  it.each([
    ['a value outside the imported type', minimal('201'), /maxResults/],
    ['a non-numeric value', minimal('abc'), /maxResults/],
    ['an undeclared root element', minimal('50', 'searchGuestResponse'), /searchGuestResponse/],
  ])('rejects %s with an error', async (_, xml, pattern) => {
    const result = await validateAgainst(xml, set);
    expect(result.valid).toBe(false);
    expect(result.errors.length).toBeGreaterThan(0);
    expect(result.errors.join('\n')).toMatch(pattern);
  });

  it('rejects searchGuestRequest in the wrong namespace', async () => {
    const xml = minimal('50').replace(NS.svc, 'urn:test:wrong-namespace');
    const result = await validateAgainst(xml, set);
    expect(result.valid).toBe(false);
    expect(result.errors.length).toBeGreaterThan(0);
  });

  it('extracts a standalone Body payload that keeps every namespace URI', () => {
    for (const { name, xml } of requestEnvelopeCases()) {
      const payload = parseXml(extractBodyPayload(xml)).documentElement;
      expect(payload?.namespaceURI, name).toBe(NS.svc);
      expect(payload?.localName, name).toBe('searchGuestRequest');
      // Every element keeps the namespace it had inside the envelope.
      const original = find(parseXml(xml), [EL.envelope, EL.body, EL.searchGuestRequest]);
      const idsOf = (el: Parameters<typeof childElements>[0]): string[] =>
        childElements(el).flatMap((c) => [
          '{' + String(c.namespaceURI) + '}' + String(c.localName),
          ...idsOf(c),
        ]);
      expect(idsOf(payload as NonNullable<typeof payload>), name).toEqual(
        idsOf(original as NonNullable<typeof original>),
      );
    }
  });

  it('validates real mapper envelopes end to end through extraction', async () => {
    for (const { name, xml } of requestEnvelopeCases()) {
      const result = await validateAgainst(extractBodyPayload(xml), set);
      expect(result, name).toEqual({ valid: true, errors: [] });
    }
  });

  it('rejects an envelope without a searchGuestRequest Body payload', () => {
    const xml = '<soap:Envelope xmlns:soap="' + NS.soap + '"><soap:Body/></soap:Envelope>';
    expect(() => extractBodyPayload(xml)).toThrow(/searchGuestRequest not found/);
  });
});
